import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, evaluateAll, depsOf, formatValue } from './formula.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let sheet
try {
  sheet = parseSheet(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}

const out = []
if (mode === 'values') {
  const vals = evaluateAll(sheet)
  for (const c of sheet.cells) out.push(`${c.addr}=${formatValue(vals.get(c.addr))}`)
} else {
  for (const c of sheet.cells) {
    let line = `${c.addr}:`
    if (c.content.startsWith('=')) {
      for (const a of depsOf(parseFormula(c.content.slice(1)))) line += ` ${a}`
    }
    out.push(line)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

