{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261012T225244Z/cell-rigfm8/src/formula.js","content":"import { parseAddr, colName } from './sheet.js'

const num = (v) => ({ t: 'num', v })
const err = (v) => ({ t: 'err', v })
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

// ---------- tokenizer / parser ----------
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { bad: true }
  let p = 0
  let misplaced = false
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const BAD = new Error('bad')

  function range(a, b) { return { t: 'range', a: a.v, b: b.v } }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) throw BAD
    if (t.k === 'num') { p++; return { t: 'lit', v: num(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw BAD
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { t: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw BAD
        }
        return { t: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word' || isKeyword(t2.v)) throw BAD
        p++
        if (isOp('(')) throw BAD
        if (isKeyword(t.v)) throw BAD
        misplaced = true
        return range(t, t2)
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { t: 'lit', v: { t: 'bool', v: true } }
      if (u === 'FALSE') return { t: 'lit', v: { t: 'bool', v: false } }
      return { t: 'ref', name: t.v }
    }
    throw BAD
  }
  function isKeyword(w) { const u = w.toUpperCase(); return u === 'TRUE' || u === 'FALSE' }
  function arg() {
    // direct range
    if (toks[p] && toks[p].k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':' &&
        toks[p + 2] && toks[p + 2].k === 'word') {
      const nx = toks[p + 3]
      if (nx && nx.k === 'op' && (nx.v === ',' || nx.v === ')') && !isKeyword(toks[p].v) && !isKeyword(toks[p + 2].v)) {
        const r = range(toks[p], toks[p + 2])
        p += 3
        return r
      }
    }
    return cmp()
  }

  try {
    const e = cmp()
    if (p !== toks.length) return { bad: true }
    return { ast: e, misplaced }
  } catch (x) {
    if (x === BAD) return { bad: true }
    throw x
  }
}

// ---------- dependencies ----------
function rangeCells(r) {
  const a = parseAddr(r.a)
  const b = parseAddr(r.b)
  if (!a || !b) return null
  const out = []
  const c0 = Math.min(a.col, b.col), c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row), r1 = Math.max(a.row, b.row)
  for (let c = c0; c <= c1; c++) for (let w = r0; w <= r1; w++) out.push(colName(c) + w)
  return out
}

export function depsOf(parsed) {
  if (parsed.bad) return []
  const set = new Map()
  const add = (name, col, row) => set.set(name, { col, row, name })
  const walk = (n) => {
    switch (n.t) {
      case 'ref': { const a = parseAddr(n.name); if (a) add(a.name, a.col, a.row); break }
      case 'range': {
        const a = parseAddr(n.a), b = parseAddr(n.b)
        if (a && b) {
          for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
            for (let w = Math.min(a.row, b.row); w <= Math.max(a.row, b.row); w++) add(colName(c) + w, c, w)
        }
        break
      }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(parsed.ast)
  return [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((x) => x.name)
}

// ---------- evaluation ----------
function readNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'err') return v
  return err('#VALUE!')
}

function finite(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
const rank = { num: 0, str: 1, bool: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] < rank[b.t] ? -1 : 1
  if (a.t === 'str') return cpCompare(a.v, b.v)
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

function literalValue(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.includes(content)) return err(content)
  return { t: 'str', v: content }
}

export function evaluateAll(sheet) {
  const memo = new Map()
  const busy = new Set()
  const parsedCache = new Map()

  function cellValue(name) {
    const a = parseAddr(name)
    if (!a) return err('#REF!')
    const key = a.name
    const cell = sheet.map.get(key)
    if (!cell) return num(0)
    if (memo.has(key)) return memo.get(key)
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    let v
    if (cell.content.startsWith('=')) {
      const parsed = parseFormula(cell.content.slice(1))
      parsedCache.set(key, parsed)
      v = parsed.bad || parsed.misplaced ? err('#ERR!') : ev(parsed.ast)
    } else v = literalValue(cell.content)
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function expand(n) {
    const cells = rangeCells(n)
    if (!cells) return [err('#REF!')]
    return cells.map(cellValue)
  }

  function ev(n) {
    switch (n.t) {
      case 'lit': return n.v
      case 'ref': return cellValue(n.name)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = readNum(ev(n.e))
        if (v.t === 'err') return v
        return n.op === '-' ? num(-v.v) : v
      }
      case 'bin': return bin(n)
      case 'call': return call(n)
    }
  }

  function bin(n) {
    const l = ev(n.l)
    const r = ev(n.r)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (l.t === 'err') return l
      if (r.t === 'err') return r
      const c = compare(l, r)
      const b = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'bool', v: b }
    }
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    const a = readNum(l)
    if (a.t === 'err') return a
    const b = readNum(r)
    if (b.t === 'err') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
  }

  function call(n) {
    const f = n.name
    const argc = n.args.length
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(f)) {
      if (argc < 1) return err('#ERR!')
      const vals = []
      for (const a of n.args) {
        if (a.t === 'range') vals.push(...expand(a))
        else vals.push(ev(a))
      }
      const e = vals.find((v) => v.t === 'err')
      if (e) return e
      if (f === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
      const nums = []
      for (const v of vals) {
        const r = readNum(v)
        if (r.t === 'err') return r
        nums.push(r.v)
      }
      if (f === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
      if (f === 'MIN') return num(Math.min(...nums))
      if (f === 'MAX') return num(Math.max(...nums))
      return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
    if (f === 'ABS') {
      if (argc !== 1) return err('#ERR!')
      let v
      if (n.args[0].t === 'range') {
        const vs = expand(n.args[0])
        const e = vs.find((x) => x.t === 'err')
        if (e) return e
        if (vs.length !== 1) return err('#ERR!')
        v = vs[0]
      } else v = ev(n.args[0])
      const r = readNum(v)
      if (r.t === 'err') return r
      return num(Math.abs(r.v))
    }
    if (f === 'IF') {
      if (argc !== 3) return err('#ERR!')
      if (n.args.some((a) => a.t === 'range')) return err('#ERR!')
      const c = ev(n.args[0])
      if (c.t === 'err') return c
      let b
      if (c.t === 'bool') b = c.v
      else if (c.t === 'num') b = c.v !== 0
      else return err('#VALUE!')
      return ev(n.args[b ? 1 : 2])
    }
    return err('#NAME?')
  }

  const result = new Map()
  for (const c of sheet.cells) result.set(c.addr, cellValue(c.addr))
  return result
}

export function formatValue(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}
"}

