{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261012T225244Z/cell-rigfm8/src/sheet.js","content":"export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  let col = 0
  for (const ch of L) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, name: L + row }
}

export function colName(col) {
  let s = ''
  while (col > 0) {
    const r = (col - 1) % 26
    s = String.fromCharCode(65 + r) + s
    col = Math.floor((col - 1) / 26)
  }
  return s
}

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const map = new Map()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const addrText = m[1]
    const content = m[2]
    const a = parseAddr(addrText)
    if (!a) throw fail(`line ${i + 1}: invalid cell address ${addrText}`)
    if (map.has(a.name)) throw fail(`line ${i + 1}: cell ${a.name} is declared twice`)
    const cell = { addr: a.name, col: a.col, row: a.row, content }
    map.set(a.name, cell)
    cells.push(cell)
  })
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return { map, cells }
}
